INSERT INTO `categories` (`id`, `name`, `slug`, `description`, `image`, `banner`, `sort_order`, `status`, `seo_title`, `seo_description`, `created_at`) VALUES (1,'Period Panties','period-panties','High absorbency, multi-layer leakproof period underwear engineered for heavy, medium, and light flow days.','cat_period_panties.svg','banner_period_panties.svg',1,'active',NULL,NULL,'2026-10-16 18:19:47'),(2,'Everyday Panties','everyday-panties','Buttery-soft, breathable bamboo and micro-modal panties designed for zero wedgies and daily all-day comfort.','cat_everyday_panties.svg','banner_everyday_panties.svg',2,'active',NULL,NULL,'2026-10-16 18:19:47'),(3,'Period Kits','period-kits','Curated confidence boxes, starter hampers, and travel packs with period underwear, pads, and hygiene essentials.','cat_period_kits.svg','banner_period_kits.svg',3,'active',NULL,NULL,'2026-10-16 18:19:47'),(4,'Pads & Liners','pads-and-liners','Rash-free 100% certified organic cotton pads, extra-long overnight wings, and biodegradable ultra-slim panty liners.','cat_pads_liners.svg','banner_pads_liners.svg',4,'active',NULL,NULL,'2026-10-16 18:19:47'),(5,'Intimate Care','intimate-care','Dermatologically tested pH 3.8 foaming washes, soothing anti-chafing sticks, and natural period panty stain cleansers.','cat_intimate_care.svg','banner_intimate_care.svg',5,'active',NULL,NULL,'2026-10-16 18:19:47'),(6,'Combos & Value Packs','combos','Multi-packs and curated bundles designed to give you maximum value while building your complete period routine.','cat_combos.svg','banner_combos.svg',6,'active',NULL,NULL,'2026-10-16 18:19:47');
