INSERT INTO `products` (`id`, `name`, `slug`, `sku`, `category_id`, `subcategory_id`, `collection_id`, `brand`, `short_description`, `description`, `specifications`, `material`, `care_instructions`, `hygiene_notice`, `size_chart`, `mrp`, `price`, `discount_percent`, `stock`, `low_stock_threshold`, `weight_grams`, `shipping_class`, `gst_percent`, `status`, `is_featured`, `is_bestseller`, `is_new_arrival`, `tags`, `primary_image`, `video_url`, `video_file`, `rating_avg`, `rating_count`, `seo_title`, `seo_description`, `seo_keywords`, `created_at`, `updated_at`) VALUES (1,'AFOREHEALTH UltraDry Heavy Flow Period Panty (4-Layer Gusset)','ultradry-heavy-flow-period-panty','AFH-PP-001',1,1,1,'AFOREHEALTH','Holds up to 4 regular pads worth of flow (40ml). 4-layer breathable leakproof barrier for 12 hours of dry comfort.','Designed specifically for heavy days and overnight peace of mind. Our proprietary 4-layer gusset technology pairs moisture-wicking organic cotton against your skin with an ultra-absorbent core and a waterproof yet breathable TPU barrier. No rustling sounds, no sweaty plastic feel, and zero stains on your bedsheets.',NULL,'Body: 95% Organic Bamboo Cotton, 5% Spandex. Gusset: Moisture-wicking cotton, microfibre absorbent layer, breathable waterproof TPU membrane.','Rinse in cold tap water until water runs clear. Machine wash with mild detergent on gentle cycle. Do NOT use bleach or fabric softeners. Line dry in shade.','Hygiene Notice: For personal intimate health, this product is hygienically sealed. Wash thoroughly before first wear. Eligible for 7-day size exchange only if unopened and unwashed.',NULL,1199.00,849.00,29,180,5,150,'standard',12.00,'published',1,1,0,NULL,'prod_ultradry_heavy_flow_period_panty.svg',NULL,NULL,4.90,248,'AFOREHEALTH UltraDry Heavy Flow Period Panty (4-Layer Gusset) | AFOREHEALTH','Holds up to 4 regular pads worth of flow (40ml). 4-layer breathable leakproof barrier for 12 hours of dry comfort.',NULL,'2026-10-16 18:19:48','2026-10-16 18:19:48'),(2,'AFOREHEALTH Overnight SleepShield Boxer Period Panty','overnight-sleepshield-boxer-period-panty','AFH-PP-002',1,1,1,'AFOREHEALTH','Boy-short style with 360-degree front-to-back coverage. Zero side-leaks even if you sleep on your tummy or sides.','Sleep in whatever position you love. The SleepShield Boxer features an extra-long gusset that extends all the way from the front waistband to the back rim. Made with ultra-soft modal fabric that stretches with your body without pinching your inner thighs.',NULL,'Body: 92% MicroModal, 8% Elastane. Gusset: 4-Layer Antibacterial Leakproof Core.','Cold rinse -> gentle cycle wash -> air dry. Do not iron or dry clean.','Intimate apparel hygiene standards apply. Try on over regular underwear to test fit.',NULL,1399.00,999.00,29,120,5,150,'standard',12.00,'published',1,1,1,NULL,'prod_overnight_sleepshield_boxer_period_panty.svg',NULL,NULL,4.80,134,'AFOREHEALTH Overnight SleepShield Boxer Period Panty | AFOREHEALTH','Boy-short style with 360-degree front-to-back coverage. Zero side-leaks even if you sleep on your tummy or sides.',NULL,'2026-10-16 18:19:48','2026-10-16 18:19:48'),(3,'AFOREHEALTH Seamless Mid-Waist Period Hipster','seamless-mid-waist-period-hipster','AFH-PP-003',1,2,1,'AFOREHEALTH','Bonded laser-cut edges for invisible zero panty lines. Absorbs up to 25ml for medium flow days.','Wear your favourite leggings, tight yoga pants, or fitted churidars with zero telltale underwear lines or bulky pad bulges. The AFOREHEALTH Seamless Mid-Waist Period Hipster combines laser-bonded edges with an ultra-thin 3-layer absorbent core.',NULL,'Body: 80% Polyamide, 20% Elastane. Gusset: 100% Breathable Cotton.','Hand wash or gentle machine wash inside a laundry mesh bag. Dry away from direct heating elements.','Hygienically packaged. Anti-odour silver-ion weave technology.',NULL,1099.00,799.00,27,150,5,150,'standard',12.00,'published',1,0,1,NULL,'prod_seamless_mid_waist_period_hipster.svg',NULL,NULL,4.70,92,'AFOREHEALTH Seamless Mid-Waist Period Hipster | AFOREHEALTH','Bonded laser-cut edges for invisible zero panty lines. Absorbs up to 25ml for medium flow days.',NULL,'2026-10-16 18:19:48','2026-10-16 18:19:48'),(4,'AFOREHEALTH Organic Bamboo Cotton Day-Flow Brief','organic-bamboo-cotton-day-flow-brief','AFH-PP-004',1,2,0,'AFOREHEALTH','Naturally antibacterial bamboo cotton. Ideal for workday confidence, office hours, and commutes.','Crafted from organically grown bamboo fibres that stay 2-3 degrees cooler than synthetic fabrics, making it an absolute lifesaver for humid Indian summers and long days away from home.',NULL,'95% Certified Organic Bamboo, 5% Spandex. 3-layer absorbent gusset.','Cold water rinse, mild liquid detergent, line dry.','Dermatologist tested. Hypoallergenic and naturally odour-neutralizing.',NULL,999.00,699.00,30,160,5,150,'standard',12.00,'published',0,1,0,NULL,'prod_organic_bamboo_cotton_day_flow_brief.svg',NULL,NULL,4.80,180,'AFOREHEALTH Organic Bamboo Cotton Day-Flow Brief | AFOREHEALTH','Naturally antibacterial bamboo cotton. Ideal for workday confidence, office hours, and commutes.',NULL,'2026-10-16 18:19:48','2026-10-16 18:19:48'),(5,'AFOREHEALTH High-Rise Tummy Support Period Panty','high-rise-tummy-support-period-panty','AFH-PP-005',1,1,4,'AFOREHEALTH','Gentle abdominal compression provides comforting warm embrace for menstrual cramps and bloating.','Periods often bring bloating and menstrual cramps. Our High-Rise Tummy Support Period Panty features a double-layered compressive front panel that gently supports your lower belly while offering heavy-flow 35ml absorbency.',NULL,'Body: 88% Cotton, 12% Spandex. Panel: Reinforced micro-compression band.','Gentle cold wash, air dry in shade.','Supports post-delivery lochia bleeding and high-cramp cycles.',NULL,1299.00,899.00,31,95,5,150,'standard',12.00,'published',0,1,0,NULL,'prod_high_rise_tummy_support_period_panty.svg',NULL,NULL,4.90,110,'AFOREHEALTH High-Rise Tummy Support Period Panty | AFOREHEALT