INSERT INTO `banners` (`id`, `title`, `subtitle`, `image_desktop`, `image_mobile`, `video_url`, `link`, `cta_text`, `position`, `sort_order`, `status`) VALUES (1,'Comfort That Moves With You.','Leakproof underwear, buttery-soft everyday panties, and pH-balanced intimate essentials engineered for Indian bodies.','hero_banner_1.svg','hero_banner_1.svg',NULL,'/category/period-panties','SHOP PERIOD PANTIES','home_hero',1,'active'),(2,'CloudSoft MicroModal Panties','3x softer than cotton with breathable 4-way stretch. Zero wedgies, zero pinch, pure everyday luxury.','hero_banner_2.svg','hero_banner_2.svg',NULL,'/category/everyday-panties','EXPLORE EVERYDAY WEAR','home_hero',2,'active'),(3,'First Period Confidence Kit','Empowering teenage girls with leakproof underwear, organic cotton pads, and discreet carry pouches.','hero_banner_3.svg','hero_banner_3.svg',NULL,'/category/period-kits','SHOP STARTER KITS','home_hero',3,'active');
