INSERT INTO `blog_categories` (`id`, `name`, `slug`, `created_at`) VALUES (1,'Period Health & Science','period-health-science','2026-10-16 18:19:49'),(2,'Product & Sizing Guides','product-sizing-guides','2026-10-16 18:19:49'),(3,'Intimate Hygiene & Wellness','intimate-hygiene-wellness','2026-10-16 18:19:49'),(4,'Sustainable Living','sustainable-living','2026-10-16 18:19:49');
