INSERT INTO `pages` (`id`, `slug`, `title`, `content`, `seo_title`, `seo_description`, `updated_at`) VALUES (1,'about-us','About AFOREHEALTH','<h2>Everyday Comfort. Period Confidence.</h2><p>AFOREHEALTH was born out of a simple, undeniable truth: modern Indian women deserve intimate care products that truly understand their bodies, climate, and everyday challenges.</p><p>For generations, menstruation has been shrouded in silence and accompanied by scratchy plastic pads, painful rashes, stained clothes, and awkward whispers. We are on a mission to change that narrative completely.</p><h3>Designed for Indian Women, by Women</h3><p>From humid summer commutes in Mumbai to long college lectures in Delhi, our products are thoughtfully engineered with breathable organic bamboo, skin-friendly micro-modal, and medical-grade leakproof barriers tailored specifically to Indian hip-to-waist ratios.</p><p>We believe that when you feel comfortable in your skin and confident in your cycle, nothing can hold you back.</p>',NULL,NULL,'2026-10-16 18:19:50'),(2,'shipping-policy','Shipping & Delivery Policy','<h2>Reliable & Discreet Delivery Across India</h2><p>At AFOREHEALTH, we understand the importance of timely and discreet delivery when it comes to intimate wellness essentials.</p><h3>1. Shipping Charges</h3><ul><li><strong>Orders above ₹499:</strong> FREE Shipping across India.</li><li><strong>Orders below ₹499:</strong> Standard flat rate of ₹50.</li><li><strong>Cash on Delivery (COD):</strong> Nominal handling fee of ₹40 applicable on COD orders.</li></ul><h3>2. Delivery Timelines</h3><ul><li>Metro Cities (Mumbai, Delhi NCR, Bengaluru, Hyderabad, Chennai, Kolkata, Pune): <strong>2 to 4 Business Days</strong></li><li>Tier 2 & Tier 3 Cities: <strong>4 to 6 Business Days</strong></li><li>North-East & Remote Locations: <strong>5 to 7 Business Days</strong></li></ul><h3>3. 100% Discreet Packaging Guaranteed</h3><p>Your privacy is sacred to us. All packages are shipped in tamper-evident, unmarked boxes or opaque security bags with zero mention of \'period panties\' or \'intimate wear\' on the external label.</p>',NULL,NULL,'2026-10-16 18:19:50'),(3,'return-refund-policy','Return, Exchange & Refund Policy','<h2>Hygiene First Policy</h2><p>Because intimate wear, period panties, and menstrual care products touch your most sensitive personal areas, strict health and hygiene regulations govern our return process.</p><h3>Eligibility for Returns & Exchanges</h3><ul><li>Products must be completely <strong>unworn, unwashed, and in their original sealed hygienic packaging</strong> with tags intact.</li><li>Requests must be initiated within <strong>7 days</strong> of delivery through your AFOREHEALTH account or by emailing info@aforehealth.com.</li><li>Items with broken hygiene liners or opened seals cannot be returned due to hygiene reasons.</li><li>In the rare event of a manufacturing defect or wrong product dispatched, we will provide a 100% free replacement or full refund immediately.</li></ul><h3>Refund Timelines</h3><p>Once your returned item arrives at our fulfillment facility and clears our hygiene inspection, your refund will be processed within 48 hours to your original payment mode or store wallet.</p>',NULL,NULL,'2026-10-16 18:19:50'),(4,'privacy-policy','Privacy & Data Protection Policy','<h2>Your Privacy Matters</h2><p>AFOREHEALTH is committed to safeguarding your personal data with enterprise-grade encryption. We do not sell, rent, or trade your personal information to third parties.</p><h3>Information We Collect</h3><ul><li>Mobile Number & Name (for OTP authentication and order fulfillment)</li><li>Shipping address and contact details</li><li>Anonymous analytics data (browser type, session duration) to enhance your shopping experience</li></ul><h3>Payment Security</h3><p>We do not store your credit card numbers, debit card details, or UPI pins. All online transactions are encrypted via 256-bit SSL and processed directly through PCI-DSS certified gateway Razorpay.</p>',NULL,NULL,'2026-10-16 18:19:50'),(5,'terms-conditions','Terms & Conditions','<h2>Terms of Use</h2><p>Welcome to AFOREHEALTH (aforehealth.com). By browsing or purchasing from our platform, you agree to comply with our standard terms of service.</p><h3>Product Usage & Medical Disclaimer</h3><p>Our period care and intimate hygiene products are designed for everyday menstrual management and personal comfort. They are not intended to diagnose, treat, cure, or prevent any medical disease or infection. If you experience abnormal menstrual symptoms or chronic pelvic pain, please consult a registered medical practitioner.</p>',NULL,NULL,'2026-10-16 18:19:50'),(6,'cancellation-policy','Cancellation Policy','<h2>Easy Order Cancellation</h2><p>You can cancel your order at any time before it has been dispatched from our fulfillment warehouse.</p><ul><li>To cancel, visit <strong>My Account > My Orders</strong> and click \'Cancel Order\', or message our WhatsApp support team at +91 98765 43210.</li><li>If the order has already been shipped, you can refuse acceptance at the time of delivery. Once the parcel returns to us, your refund will be initiated automatically.</li></ul>',NULL,NULL,'2026-10-16 18:19:50');
